/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_CLAIM_CONVERSION_EVENT
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK, CONVERSION_REFERENCE
   hashdiff    : SAT_CLAIM_CONVERSION_EVENT_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 0 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     CONVERSION_DATE                        opus_health_v2         2 writer(s), of which 1 UNDISCRIMINATED (0 separated by a resolved instance, 1 by redundant_of)
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , coalesce(nullif(trim(CONV_ID), ''), '') as CONVERSION_REFERENCE
        , CONV_TYPE as CONVERSION_TYPE_CODE
        , PREV_CLAIM_ID as SUPERSEDED_CLAIM_REFERENCE
        , UPDATED_ON as CONVERSION_DATE
        , UPDATED_BY as CONVERTED_BY_USER_IDENTIFIER
        , 'BJAZ_HM_CLAIM_CONVERSION' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_claim_conversion') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        CONVERSION_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then CONVERSION_TYPE_CODE end) as CONVERSION_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUPERSEDED_CLAIM_REFERENCE end) as SUPERSEDED_CLAIM_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then CONVERSION_DATE end) as CONVERSION_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then CONVERTED_BY_USER_IDENTIFIER end) as CONVERTED_BY_USER_IDENTIFIER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK, CONVERSION_REFERENCE
),

hashed as (
    select
        *,
        case when CONVERSION_REFERENCE is not null or CONVERSION_TYPE_CODE is not null or SUPERSEDED_CLAIM_REFERENCE is not null or CONVERSION_DATE is not null or CONVERTED_BY_USER_IDENTIFIER is not null
                     then md5(upper(coalesce(cast(CONVERSION_REFERENCE as varchar), '') || '|' || coalesce(cast(CONVERSION_TYPE_CODE as varchar), '') || '|' || coalesce(cast(SUPERSEDED_CLAIM_REFERENCE as varchar), '') || '|' || coalesce(cast(CONVERSION_DATE as varchar), '') || '|' || coalesce(cast(CONVERTED_BY_USER_IDENTIFIER as varchar), '')))
                end as SAT_CLAIM_CONVERSION_EVENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_CONVERSION_EVENT_HASHDIFF is not null
